<div class="page-title clearfix"><h1><?php echo esc($movement->folio); ?> <span class="badge bg-<?php echo$movement->status==='confirmed'?'success':($movement->status==='draft'?'warning':'secondary'); ?>"><?php echo esc($movement->status); ?></span></h1></div><div class="row"><div class="col-md-9"><div class="card card-body"><div class="row"><div class="col-md-3"><b>Tipo</b><br><?php echo esc($movement->movement_type); ?></div><div class="col-md-3"><b>Almacén</b><br><?php echo esc($movement->warehouse_name); ?></div><div class="col-md-3"><b>Fecha</b><br><?php echo esc($movement->movement_date); ?></div><div class="col-md-3"><b>Referencia</b><br><?php echo esc($movement->reference_text?:'-'); ?></div></div><hr><table class="table"><thead><tr><th>Producto</th><th>Código</th><th>Cantidad</th><th>Delta</th><th>Unidad</th></tr></thead><tbody><?php foreach($lines as$l): ?><tr><td><?php echo esc($l->product_name); ?></td><td><?php echo esc($l->internal_code); ?></td><td><?php echo esc(to_decimal_format($l->quantity)); ?></td><td><?php echo esc(to_decimal_format($l->quantity_delta)); ?></td><td><?php echo esc($l->control_unit); ?></td></tr><?php endforeach; ?></tbody></table><hr><small>Creado por <?php echo esc(trim($movement->creator_name)); ?> · Confirmado por <?php echo esc(trim($movement->confirmer_name)?:'-'); ?></small><?php if($movement->status==='cancelled'): ?><div class="alert alert-secondary mt10"><b>Cancelado:</b> <?php echo esc($movement->cancelled_at); ?><br><?php echo nl2br(esc($movement->cancellation_reason)); ?></div><?php endif; ?></div></div><div class="col-md-3"><div class="card card-body"><h5>Acciones</h5><?php if($can_confirm&&$movement->status==='draft'): ?><button id="confirm-movement" class="btn btn-primary mb10">Confirmar movimiento</button><?php elseif($can_confirm&&$movement->status==='confirmed'): ?><textarea id="cancel-reason" class="form-control mb10" placeholder="Motivo obligatorio"></textarea><button id="cancel-movement" class="btn btn-danger">Cancelar movimiento</button><?php else: ?><p class="text-muted">Documento en modo lectura.</p><?php endif; ?></div></div></div><script>$('#confirm-movement').click(function(){$.post('<?php echo get_uri('warehouses/movements/'.$movement->id.'/confirm'); ?>',{'<?php echo csrf_token(); ?>':'<?php echo csrf_hash(); ?>'},function(r){appAlert.success(r.message);location.reload();},'json').fail(function(x){appAlert.error((x.responseJSON||{}).message);});});$('#cancel-movement').click(function(){$.post('<?php echo get_uri('warehouses/movements/'.$movement->id.'/cancel'); ?>',{reason:$('#cancel-reason').val(),'<?php echo csrf_token(); ?>':'<?php echo csrf_hash(); ?>'},function(r){appAlert.success(r.message);location.reload();},'json').fail(function(x){appAlert.error((x.responseJSON||{}).message);});});</script>
